static inline v128 vfrecpe32(v128 a) { LANES32(a, frecpe_f32(e)); }
static inline v128 vfrecpe64(v128 a) { LANES64(a, frecpe_f64(e)); }
static inline v128 vfrsqrte32(v128 a) { LANES32(a, frsqrte_f32(e)); }
